-- S008: harvest tables + the photo hashes added this session.
-- Run on the REAL database on Christopher's machine (the sandbox mount
-- cannot journal sqlite):
--     cd ~/borgovero/phase0
--     sqlite3 phase0.sqlite < apply_S008_data.sql
-- Idempotent: INSERT OR REPLACE throughout. Does NOT touch listings,
-- price_history, or any existing row. Typology corrections are separate:
--     python3 apply_S008_typology.py
CREATE TABLE IF NOT EXISTS agency_site_listings (
    site TEXT NOT NULL, url TEXT NOT NULL, ref TEXT, price INTEGER,
    price_withheld INTEGER DEFAULT 0, mq INTEGER, comune TEXT,
    comune_raw TEXT, title TEXT, is_rent INTEGER DEFAULT 0,
    harvested_on TEXT, PRIMARY KEY (site, url));
CREATE TABLE IF NOT EXISTS url_alt (
    source TEXT NOT NULL, source_id TEXT NOT NULL, site TEXT NOT NULL,
    url_alt TEXT NOT NULL, match_route TEXT NOT NULL,
    site_ref TEXT, site_price INTEGER, site_mq INTEGER,
    site_comune TEXT, site_title TEXT, matched_on TEXT,
    PRIMARY KEY (source, source_id, site));
DELETE FROM agency_site_listings;
DELETE FROM url_alt;
